import { photoSizes } from './photos.generated'

// Photos are generated by `npm run photos` (scripts/process-photos.mjs) from
// the originals in old_resources/website_pics/ into public/photos/:
// <slug>-1200.jpg and <slug>-2048.jpg. The slug is the original file name,
// lower-cased and hyphenated ("Olympic 5.jpeg" → "olympic-5").
export type Photo = { slug: string; caption: string; location: string }

export const photoSrc = (slug: string, size: 1200 | 2048 = 1200) => `/photos/${slug}-${size}.jpg`
export const photoSrcSet = (slug: string) => `${photoSrc(slug, 1200)} 1200w, ${photoSrc(slug, 2048)} 2048w`
/** Width / height of the photo (falls back to 3:2 for unknown slugs). */
export const photoAspect = (slug: string) => {
  const s = photoSizes[slug]
  return s ? s.w / s.h : 1.5
}

